# dashboard_template.py — Hilo V8.5.0
import base64

# ─────────────────────────────────────────────────────────────────────────────
# _B64 : Template HTML complet du Dashboard Tension (Stats & Distribution)
# Encodé en base64 pour préserver l'intégrité du contenu (HTML/CSS/JS imbriqués)
# Pour modifier : base64.b64decode(_B64).decode('utf-8') → éditer → re-encoder
# Contient : sidebar filtres (dates, raccourcis, heure mesure, bouton 💤 PPC),
#            graphiques (distribution Sys/Dia/FC, courbes, cible, grille),
#            fonctions JS : applyShortcut(), setHour(), applyFilters(), etc.
# ─────────────────────────────────────────────────────────────────────────────
_B64 = """

"""

DASHBOARD_TEMPLATE = base64.b64decode(_B64.strip()).decode('utf-8')

def render_dashboard(records_json, date_min, date_max, generated, n_total,
                     cible_sys=130, cible_dia=80, cible_fc=60,
                     jour_debut=6, jour_fin=22, patient_header="",
                     date_min_eu="", date_max_eu="", ppc_sessions="[]"):
    html = DASHBOARD_TEMPLATE
    html = html.replace('%%PPC_SESSIONS%%',   ppc_sessions)
    html = html.replace('%%RECORDS%%',        records_json)
    html = html.replace('%%DATE_MIN%%',       date_min)
    html = html.replace('%%DATE_MAX%%',       date_max)
    html = html.replace('%%DATE_MIN_EU%%',    date_min_eu or date_min)
    html = html.replace('%%DATE_MAX_EU%%',    date_max_eu or date_max)
    html = html.replace('%%GENERATED%%',      generated)
    html = html.replace('%%N_TOTAL%%',        str(n_total))
    html = html.replace('%%CIBLE_SYS%%',      str(cible_sys))
    html = html.replace('%%CIBLE_DIA%%',      str(cible_dia))
    html = html.replace('%%CIBLE_FC%%',       str(cible_fc))
    html = html.replace('%%JOUR_DEBUT%%',     str(jour_debut))
    html = html.replace('%%JOUR_FIN%%',       str(jour_fin))
    html = html.replace('%%PATIENT_HEADER%%', patient_header)
    return html
